import{_ as a,H as o,f as c,i as d}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"Plan（계획）","description":"","frontmatter":{},"headers":[],"relativePath":"ko/skills/plan.md","filePath":"ko/skills/plan.md"}'),t={name:"ko/skills/plan.md"};function s(n,e,p,l,i,r){return o(),c("div",null,[...e[0]||(e[0]=[d(`<h1 id="plan-계획" tabindex="-1">Plan（계획） <a class="header-anchor" href="#plan-계획" aria-label="Permalink to &quot;Plan（계획）&quot;">​</a></h1><p><code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>. 명세를 참조하고, 반복하지 않는다.</p><p>미해결된 명세 노트가 구현이나 작업 순서에 영향을 미치면 <code>design</code>으로 돌아간다.</p><h2 id="마일스톤-작업-각-30-60분" tabindex="-1">마일스톤 작업 (각 30~60분) <a class="header-anchor" href="#마일스톤-작업-각-30-60분" aria-label="Permalink to &quot;마일스톤 작업 (각 30~60분)&quot;">​</a></h2><p>각 작업은 <code>- [ ] T&lt;n&gt;: &lt;이름&gt;</code> — 항상 체크박스, 제목이 아님. <code>tdd</code>/<code>subagents</code>가 완료 시 <code>- [x]</code>로 변경. <code>ship</code>은 모든 <code>- [ ]</code>가 완료될 때까지 실행을 거부한다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>goal:       &lt;한 줄&gt;</span></span>
<span class="line"><span>files:      &lt;경로&gt;</span></span>
<span class="line"><span>acceptance: &lt;테스트 또는 명령어&gt;</span></span>
<span class="line"><span>spec:       &lt;docs/staging/specs/...#anchor&gt;</span></span></code></pre></div><p>정확한 코드 없음. 단계 없음. Acceptance는 실행 가능: 테스트 이름, 명령어, 또는 스크립트 확인. 각 작업은 저장소를 그린 상태로 유지한다.</p><p>독립적인 작업 표시: <code>[parallel] T3, T4, T5</code>.</p><p>공유 계약, 상태, 오류, acceptance가 닫혀있을 때만 <code>[parallel]</code> 표시.</p><p><strong>원자적 전개는 배포 시 지연</strong> — <code>subagents</code>가 배포 시 마일스톤을 2~5분 단계로 전개한다. 여기서 하지 않는다.</p><p><strong>신규 프로젝트</strong>: 초기화 작업을 파생시킨다 — 스캐폴드 코드, 테스트, CI. 항상 포함: <code>README.md</code>, <code>CHANGELOG.md</code>, <code>.gitignore</code>, <code>Makefile</code> (또는 동등한 태스크 러너 구성).</p><h2 id="계획에-포함하지-않을-것" tabindex="-1">계획에 포함하지 않을 것 <a class="header-anchor" href="#계획에-포함하지-않을-것" aria-label="Permalink to &quot;계획에 포함하지 않을 것&quot;">​</a></h2><p>배경, 아키텍처, 이유 (명세), CI 명령어, 복붙된 acceptance.</p><h2 id="롤링-웨이브" tabindex="-1">롤링 웨이브 <a class="header-anchor" href="#롤링-웨이브" aria-label="Permalink to &quot;롤링 웨이브&quot;">​</a></h2><p>명세에 <code>## Roadmap</code>이 있는가? <code>← 지금 상세 계획</code>으로 표시된 마일스톤만 전개한다. 나머지는 스텁으로 둔다.</p><p><code>ship</code> 후: <code>← 지금 상세 계획</code> 마커를 다음 마일스톤으로 이동하고 (해당 <code>← stub</code>을 <code>← 지금 상세 계획</code>으로 변경), 배운 것을 기반으로 업데이트한 후 전개한다. 마일스톤 목표가 본질적으로 바뀐 경우에만 <code>design</code>으로 돌아간다.</p><h2 id="gate" tabindex="-1">Gate <a class="header-anchor" href="#gate" aria-label="Permalink to &quot;Gate&quot;">​</a></h2><p><code>tdd</code>/<code>subagents</code>에 인계하기 전에 <code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>가 디스크에 존재해야 한다.</p><p>사용자와 계획을 확인한다.</p><p><code>[parallel]</code>이 많음 → <code>subagents</code>. 그렇지 않으면 → <code>tdd</code>.</p>`,20)])])}const u=a(t,[["render",s]]);export{g as __pageData,u as default};
